import React, { useState } from 'react';
import { Container, Row, Col, Card, Table, Badge, Alert, Spinner, Nav, Tab } from 'react-bootstrap';
import { useNavigate } from 'react-router-dom';
import { usePortfolio } from '../context/PortfolioContext';
import { Line, Pie, Bar } from 'react-chartjs-2';
import { Chart as ChartJS, CategoryScale, LinearScale, PointElement, LineElement, Title, Tooltip, Legend, ArcElement, BarElement } from 'chart.js';

// Register ChartJS components
ChartJS.register(
  CategoryScale,
  LinearScale,
  PointElement,
  LineElement,
  Title,
  Tooltip,
  Legend,
  ArcElement,
  BarElement
);

// Helper function to safely format currency
const formatCurrency = (value) => {
  if (value === undefined || value === null) return '₹0.00';
  return '₹' + value.toLocaleString(undefined, { minimumFractionDigits: 2, maximumFractionDigits: 2 });
};

// Helper function to safely format percentage
const formatPercentage = (value) => {
  if (value === undefined || value === null) return '0.00%';
  return value.toFixed(2) + '%';
};

// Helper function to safely format number
const formatNumber = (value) => {
  if (value === undefined || value === null) return '0';
  return value.toLocaleString();
};

// Helper function to get sector color
const getSectorColor = (sector) => {
  const colors = {
    'Technology': '#007bff',
    'Financial Services': '#6610f2',
    'Healthcare': '#6f42c1',
    'Consumer Discretionary': '#e83e8c',
    'Consumer Staples': '#dc3545',
    'Industrials': '#fd7e14',
    'Energy': '#ffc107',
    'Materials': '#28a745',
    'Utilities': '#20c997',
    'Real Estate': '#17a2b8',
    'Communication Services': '#6c757d',
    'Other': '#343a40'
  };

  return colors[sector] || colors['Other'];
};

const PortfolioDetail = () => {
  const navigate = useNavigate();
  const { portfolio, loading, error } = usePortfolio();
  const [activeTab, setActiveTab] = useState('overview');

  if (loading) {
    return (
      <Container className="mt-5 text-center">
        <Spinner animation="border" role="status">
          <span className="visually-hidden">Loading...</span>
        </Spinner>
        <p className="mt-3">Loading portfolio data...</p>
      </Container>
    );
  }

  if (error) {
    return (
      <Container className="mt-5">
        <Alert variant="danger">
          <Alert.Heading>Error Loading Portfolio</Alert.Heading>
          <p>{error}</p>
        </Alert>
      </Container>
    );
  }

  if (!portfolio) {
    return (
      <Container className="mt-5">
        <Alert variant="info">
          <Alert.Heading>No Portfolio Found</Alert.Heading>
          <p>You don't have a portfolio loaded yet. Please import your portfolio data first.</p>
        </Alert>
      </Container>
    );
  }

  // Prepare data for charts
  const preparePerformanceChartData = () => {
    if (!portfolio.history || portfolio.history.length < 2) {
      return null;
    }

    const labels = portfolio.history.map(entry => {
      const date = new Date(entry.date);
      return date.toLocaleDateString();
    });

    const marketValueData = portfolio.history.map(entry => entry.totalValue);
    const investedValueData = portfolio.history.map(entry => entry.investedValue);

    return {
      labels,
      datasets: [
        {
          label: 'Market Value',
          data: marketValueData,
          borderColor: 'rgba(75, 192, 192, 1)',
          backgroundColor: 'rgba(75, 192, 192, 0.2)',
          tension: 0.1,
        },
        {
          label: 'Invested Value',
          data: investedValueData,
          borderColor: 'rgba(153, 102, 255, 1)',
          backgroundColor: 'rgba(153, 102, 255, 0.2)',
          tension: 0.1,
        }
      ]
    };
  };

  const prepareSectorAllocationData = () => {
    if (!portfolio.sectorAllocation) {
      return null;
    }

    const sectors = Object.keys(portfolio.sectorAllocation);
    const values = sectors.map(sector => portfolio.sectorAllocation[sector]);

    // Generate colors for each sector
    const backgroundColors = [
      'rgba(255, 99, 132, 0.6)',
      'rgba(54, 162, 235, 0.6)',
      'rgba(255, 206, 86, 0.6)',
      'rgba(75, 192, 192, 0.6)',
      'rgba(153, 102, 255, 0.6)',
      'rgba(255, 159, 64, 0.6)',
      'rgba(199, 199, 199, 0.6)',
      'rgba(83, 102, 255, 0.6)',
      'rgba(40, 159, 64, 0.6)',
      'rgba(210, 99, 132, 0.6)',
    ];

    return {
      labels: sectors,
      datasets: [
        {
          data: values,
          backgroundColor: backgroundColors.slice(0, sectors.length),
          borderWidth: 1,
        }
      ]
    };
  };

  const prepareHoldingsChartData = () => {
    if (!portfolio.holdings || portfolio.holdings.length === 0) {
      return null;
    }

    // Sort holdings by current value in descending order
    const sortedHoldings = [...portfolio.holdings].sort((a, b) => b.currentValue - a.currentValue);

    // Take top 10 holdings
    const topHoldings = sortedHoldings.slice(0, 10);

    const labels = topHoldings.map(holding => holding.symbol);
    const marketValues = topHoldings.map(holding => holding.currentValue);
    const costValues = topHoldings.map(holding => holding.costBasis);

    return {
      labels,
      datasets: [
        {
          label: 'Market Value',
          data: marketValues,
          backgroundColor: 'rgba(75, 192, 192, 0.6)',
        },
        {
          label: 'Cost Basis',
          data: costValues,
          backgroundColor: 'rgba(153, 102, 255, 0.6)',
        }
      ]
    };
  };

  const prepareHistoryChartData = () => {
    if (!portfolio.history || portfolio.history.length === 0) {
      return null;
    }

    // Create a map to count actions by type
    const actionCounts = {};

    portfolio.transactions.forEach(transaction => {
      const action = transaction.action.toUpperCase();
      if (!actionCounts[action]) {
        actionCounts[action] = 0;
      }
      actionCounts[action]++;
    });

    const labels = Object.keys(actionCounts);
    const data = Object.values(actionCounts);

    // Generate colors for each action type
    const backgroundColors = [
      'rgba(75, 192, 192, 0.6)',  // BUY - green
      'rgba(255, 99, 132, 0.6)',  // SELL - red
      'rgba(255, 206, 86, 0.6)',  // DIVIDEND - yellow
      'rgba(153, 102, 255, 0.6)', // Other
    ];

    return {
      labels,
      datasets: [
        {
          label: 'Transaction Count by Type',
          data,
          backgroundColor: backgroundColors.slice(0, labels.length),
        }
      ]
    };
  };

  const performanceChartData = preparePerformanceChartData();
  const sectorAllocationData = prepareSectorAllocationData();
  const holdingsChartData = prepareHoldingsChartData();
  const historyChartData = prepareHistoryChartData();

  const chartOptions = {
    responsive: true,
    maintainAspectRatio: false,
    plugins: {
      legend: {
        position: 'top',
      },
    },
  };

  const pieChartOptions = {
    responsive: true,
    maintainAspectRatio: false,
    plugins: {
      legend: {
        position: 'right',
      },
    },
  };

  return (
    <Container className="mt-4">
      <h1 className="mb-4">{portfolio.name || 'Portfolio Details'}</h1>

      <Row className="mb-4">
        <Col md={4}>
          <Card className="h-100">
            <Card.Body>
              <Card.Title>Portfolio Summary</Card.Title>
              <div className="d-flex flex-column">
                <div className="d-flex justify-content-between mb-2">
                  <span>Total Market Value:</span>
                  <span className="fw-bold">₹{portfolio.totalValue.toLocaleString('en-IN', { maximumFractionDigits: 2 })}</span>
                </div>
                <div className="d-flex justify-content-between mb-2">
                  <span>Total Invested:</span>
                  <span className="fw-bold">₹{portfolio.investedValue.toLocaleString('en-IN', { maximumFractionDigits: 2 })}</span>
                </div>
                <div className="d-flex justify-content-between mb-2">
                  <span>Total Gain/Loss:</span>
                  <span className={`fw-bold ${portfolio.totalGainLoss >= 0 ? 'text-success' : 'text-danger'}`}>
                    ₹{portfolio.totalGainLoss.toLocaleString('en-IN', { maximumFractionDigits: 2 })}
                    {' '}
                    ({portfolio.totalGainLossPercentage.toFixed(2)}%)
                  </span>
                </div>
                <div className="d-flex justify-content-between mb-2">
                  <span>Number of Holdings:</span>
                  <span className="fw-bold">{portfolio.holdings.length}</span>
                </div>
                <div className="d-flex justify-content-between">
                  <span>Last Updated:</span>
                  <span className="fw-bold">{new Date(portfolio.lastUpdated).toLocaleDateString()}</span>
                </div>
              </div>
            </Card.Body>
          </Card>
        </Col>

        <Col md={8}>
          <Card className="h-100">
            <Card.Body>
              <Card.Title>Portfolio Performance</Card.Title>
              {performanceChartData ? (
                <div style={{ height: '250px' }}>
                  <Line data={performanceChartData} options={chartOptions} />
                </div>
              ) : (
                <Alert variant="info">
                  Not enough historical data to display performance chart. Update your portfolio to see performance over time.
                </Alert>
              )}
            </Card.Body>
          </Card>
        </Col>
      </Row>

      <Nav variant="tabs" className="mb-4" activeKey={activeTab} onSelect={setActiveTab}>
        <Nav.Item>
          <Nav.Link eventKey="overview">Overview</Nav.Link>
        </Nav.Item>
        <Nav.Item>
          <Nav.Link eventKey="holdings">Holdings</Nav.Link>
        </Nav.Item>
        <Nav.Item>
          <Nav.Link eventKey="transactions">Transactions</Nav.Link>
        </Nav.Item>
        <Nav.Item>
          <Nav.Link eventKey="history">History</Nav.Link>
        </Nav.Item>
      </Nav>

      <Tab.Content>
        <Tab.Pane eventKey="overview" active={activeTab === 'overview'}>
          <Row>
            <Col md={6} className="mb-4">
              <Card>
                <Card.Body>
                  <Card.Title>Sector Allocation</Card.Title>
                  {sectorAllocationData ? (
                    <div style={{ height: '300px' }}>
                      <Pie data={sectorAllocationData} options={pieChartOptions} />
                    </div>
                  ) : (
                    <Alert variant="info">
                      No sector allocation data available.
                    </Alert>
                  )}
                </Card.Body>
              </Card>
            </Col>

            <Col md={6} className="mb-4">
              <Card>
                <Card.Body>
                  <Card.Title>Top Holdings</Card.Title>
                  {holdingsChartData ? (
                    <div style={{ height: '300px' }}>
                      <Bar data={holdingsChartData} options={chartOptions} />
                    </div>
                  ) : (
                    <Alert variant="info">
                      No holdings data available.
                    </Alert>
                  )}
                </Card.Body>
              </Card>
            </Col>
          </Row>

          <Row>
            <Col md={12} className="mb-4">
              <Card>
                <Card.Body>
                  <Card.Title>Top 5 Holdings (by Market Value)</Card.Title>
                  <div className="table-responsive">
                    <Table striped hover>
                      <thead>
                        <tr>
                          <th>Symbol</th>
                          <th>Company</th>
                          <th>Quantity</th>
                          <th>Avg. Cost</th>
                          <th>Current Price</th>
                          <th>Market Value</th>
                          <th>Gain/Loss</th>
                        </tr>
                      </thead>
                      <tbody>
                        {portfolio.holdings
                          .sort((a, b) => b.currentValue - a.currentValue)
                          .slice(0, 5)
                          .map((holding, index) => (
                            <tr key={index}>
                              <td>{holding.symbol}</td>
                              <td>{holding.companyName || holding.symbol}</td>
                              <td>{holding.quantity}</td>
                              <td>₹{holding.avgCostPrice.toFixed(2)}</td>
                              <td>₹{holding.currentPrice.toFixed(2)}</td>
                              <td>₹{holding.currentValue.toLocaleString('en-IN', { maximumFractionDigits: 2 })}</td>
                              <td className={holding.unrealizedPL >= 0 ? 'text-success' : 'text-danger'}>
                                ₹{holding.unrealizedPL.toLocaleString('en-IN', { maximumFractionDigits: 2 })}
                                {' '}
                                ({holding.unrealizedPLPercent.toFixed(2)}%)
                              </td>
                            </tr>
                          ))}
                      </tbody>
                    </Table>
                  </div>
                </Card.Body>
              </Card>
            </Col>
          </Row>
        </Tab.Pane>

        <Tab.Pane eventKey="holdings" active={activeTab === 'holdings'}>
          <Card>
            <Card.Body>
              <Card.Title>All Holdings</Card.Title>
              <div className="table-responsive">
                <Table striped hover>
                  <thead>
                    <tr>
                      <th>Symbol</th>
                      <th>Company</th>
                      <th>Quantity</th>
                      <th>Avg. Cost</th>
                      <th>Current Price</th>
                      <th>Cost Basis</th>
                      <th>Market Value</th>
                      <th>Gain/Loss</th>
                      <th>Gain/Loss %</th>
                    </tr>
                  </thead>
                  <tbody>
                    {portfolio.holdings
                      .sort((a, b) => b.currentValue - a.currentValue)
                      .map((holding, index) => (
                        <tr key={index}>
                          <td>{holding.symbol}</td>
                          <td>{holding.companyName || holding.symbol}</td>
                          <td>{holding.quantity}</td>
                          <td>₹{holding.avgCostPrice.toFixed(2)}</td>
                          <td>₹{holding.currentPrice.toFixed(2)}</td>
                          <td>₹{holding.costBasis.toLocaleString('en-IN', { maximumFractionDigits: 2 })}</td>
                          <td>₹{holding.currentValue.toLocaleString('en-IN', { maximumFractionDigits: 2 })}</td>
                          <td className={holding.unrealizedPL >= 0 ? 'text-success' : 'text-danger'}>
                            ₹{holding.unrealizedPL.toLocaleString('en-IN', { maximumFractionDigits: 2 })}
                          </td>
                          <td className={holding.unrealizedPLPercent >= 0 ? 'text-success' : 'text-danger'}>
                            {holding.unrealizedPLPercent.toFixed(2)}%
                          </td>
                        </tr>
                      ))}
                  </tbody>
                </Table>
              </div>
            </Card.Body>
          </Card>
        </Tab.Pane>

        <Tab.Pane eventKey="transactions" active={activeTab === 'transactions'}>
          <Card>
            <Card.Body>
              <Card.Title>Transaction History</Card.Title>
              <div className="table-responsive">
                <Table striped hover>
                  <thead>
                    <tr>
                      <th>Date</th>
                      <th>Symbol</th>
                      <th>Company</th>
                      <th>Action</th>
                      <th>Quantity</th>
                      <th>Price</th>
                      <th>Total</th>
                    </tr>
                  </thead>
                  <tbody>
                    {portfolio.transactions
                      .sort((a, b) => new Date(b.date) - new Date(a.date))
                      .map((transaction, index) => (
                        <tr key={index}>
                          <td>{new Date(transaction.date).toLocaleDateString()}</td>
                          <td>{transaction.symbol}</td>
                          <td>{transaction.companyName || transaction.symbol}</td>
                          <td>
                            <Badge bg={transaction.action.toUpperCase() === 'BUY' ? 'success' : 'danger'}>
                              {transaction.action.toUpperCase()}
                            </Badge>
                          </td>
                          <td>{transaction.quantity}</td>
                          <td>₹{transaction.price.toFixed(2)}</td>
                          <td>₹{(transaction.quantity * transaction.price).toLocaleString('en-IN', { maximumFractionDigits: 2 })}</td>
                        </tr>
                      ))}
                  </tbody>
                </Table>
              </div>
            </Card.Body>
          </Card>
        </Tab.Pane>

        <Tab.Pane eventKey="history" active={activeTab === 'history'}>
          <Row>
            <Col md={6} className="mb-4">
              <Card>
                <Card.Body>
                  <Card.Title>Transaction Types</Card.Title>
                  {historyChartData ? (
                    <div style={{ height: '300px' }}>
                      <Bar data={historyChartData} options={chartOptions} />
                    </div>
                  ) : (
                    <Alert variant="info">
                      No transaction history data available.
                    </Alert>
                  )}
                </Card.Body>
              </Card>
            </Col>

            <Col md={6} className="mb-4">
              <Card>
                <Card.Body>
                  <Card.Title>Portfolio Update History</Card.Title>
                  <div className="table-responsive">
                    <Table striped hover>
                      <thead>
                        <tr>
                          <th>Date</th>
                          <th>Action</th>
                          <th>Market Value</th>
                          <th>Invested Value</th>
                        </tr>
                      </thead>
                      <tbody>
                        {portfolio.history && portfolio.history
                          .sort((a, b) => new Date(b.date) - new Date(a.date))
                          .map((entry, index) => (
                            <tr key={index}>
                              <td>{new Date(entry.date).toLocaleDateString()}</td>
                              <td>{entry.action}</td>
                              <td>₹{entry.totalValue.toLocaleString('en-IN', { maximumFractionDigits: 2 })}</td>
                              <td>₹{entry.investedValue.toLocaleString('en-IN', { maximumFractionDigits: 2 })}</td>
                            </tr>
                          ))}
                      </tbody>
                    </Table>
                  </div>
                </Card.Body>
              </Card>
            </Col>
          </Row>
        </Tab.Pane>
      </Tab.Content>
    </Container>
  );
};

export default PortfolioDetail;
